def variance(nums: list[float]) -> float:
    if not nums:
        return 0.0
    mu = sum(nums) / len(nums)
    return sum((x - mu) ** 2 for x in nums) / len(nums)

def moving_average(nums: list[float], window: int) -> list[float]:
    if window <= 0 or window > len(nums):
        return []
    return [sum(nums[i:i+window]) / window for i in range(len(nums) - window + 1)]

def percentile(nums: list[float], p: float) -> float:
    if not nums:
        return 0.0
    s = sorted(nums)
    idx = (len(s) - 1) * (p / 100.0)
    lo = int(idx)
    hi = min(len(s) - 1, lo + 1)
    return s[lo] + (s[hi] - s[lo]) * (idx - lo)

